import 'package:auto_sudoku_solver/auto_sudoku_solver.dart';
import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Tracks how many times the player has identified each strategy by hand,
/// which strategies are unlocked for auto-solving, and which of those the
/// player has switched on.
///
/// Hints generated by the app never count towards unlocks, nor do moves made
/// by the auto-solver itself or moves made inside tutorials.
class StrategyProgress extends ChangeNotifier {
  static const int unlockThreshold = 100;

  static const String _countsPref = 'strategyMoveCounts';
  static const String _disabledPref = 'strategyAutoDisabled';
  static const String _seenPref = 'strategyUnlockSeen';
  static const String _masterPref = 'autoSolveEnabled';

  final Map<StrategyType, int> _counts = {};
  final Set<StrategyType> _disabled = {};
  final Set<StrategyType> _seen = {};
  bool _masterEnabled = true;
  SharedPreferences? _prefs;

  Future<SharedPreferences> _getPrefs() async =>
      _prefs ??= await SharedPreferences.getInstance();

  Future<void> loadAll() async {
    final prefs = await _getPrefs();

    _counts.clear();
    for (final entry in prefs.getStringList(_countsPref) ?? <String>[]) {
      final parts = entry.split(':');
      final type = _typeByName(parts.first);
      final count = parts.length == 2 ? int.tryParse(parts[1]) : null;
      if (type != null && count != null) {
        _counts[type] = count;
      }
    }

    _disabled
      ..clear()
      ..addAll(_typesFromNames(prefs.getStringList(_disabledPref)));
    _seen
      ..clear()
      ..addAll(_typesFromNames(prefs.getStringList(_seenPref)));
    _masterEnabled = prefs.getBool(_masterPref) ?? true;

    notifyListeners();
  }

  // State queries
  int countOf(StrategyType type) => _counts[type] ?? 0;

  bool isUnlocked(StrategyType type) => countOf(type) >= unlockThreshold;

  bool isEnabled(StrategyType type) => !_disabled.contains(type);

  bool get masterEnabled => _masterEnabled;

  /// True for an unlocked strategy the player hasn't yet seen in settings.
  bool isNew(StrategyType type) => isUnlocked(type) && !_seen.contains(type);

  int get unlockedCount => StrategyType.values.where(isUnlocked).length;

  /// Strategies the auto-solver may use, or null when auto-solving is off.
  SolverSettings? autoSolverSettings() {
    if (!_masterEnabled) return null;

    final allowed = StrategyType.values
        .where((t) => isUnlocked(t) && isEnabled(t))
        .toSet();
    if (allowed.isEmpty) return null;

    return SolverSettings(allowed: allowed);
  }

  // Mutations

  /// Records one successful, player-identified use of [type].
  /// Returns true if this move unlocked the strategy.
  bool record(StrategyType type) {
    final before = countOf(type);
    // Stop counting once unlocked; the number is only used for progress.
    if (before >= unlockThreshold) return false;

    _counts[type] = before + 1;
    notifyListeners();
    _persistCounts();

    return _counts[type] == unlockThreshold;
  }

  void setMasterEnabled(bool value) {
    if (_masterEnabled == value) return;
    _masterEnabled = value;
    notifyListeners();
    _getPrefs().then((p) => p.setBool(_masterPref, value));
  }

  void setEnabled(StrategyType type, bool value) {
    if (!isUnlocked(type)) return;
    final changed = value ? _disabled.remove(type) : _disabled.add(type);
    if (!changed) return;
    notifyListeners();
    _getPrefs().then(
      (p) => p.setStringList(_disabledPref, _names(_disabled)),
    );
  }

  /// Clears the "New" badges. Intentionally silent so it can run on dispose.
  void markAllSeen() {
    final unseen = StrategyType.values.where(isNew).toList();
    if (unseen.isEmpty) return;
    _seen.addAll(unseen);
    _getPrefs().then((p) => p.setStringList(_seenPref, _names(_seen)));
  }

  Future<void> resetAll() async {
    _counts.clear();
    _disabled.clear();
    _seen.clear();
    _masterEnabled = true;
    notifyListeners();

    final prefs = await _getPrefs();
    await prefs.remove(_countsPref);
    await prefs.remove(_disabledPref);
    await prefs.remove(_seenPref);
    await prefs.remove(_masterPref);
  }

  // Persistence helpers
  Future<void> _persistCounts() async {
    final prefs = await _getPrefs();
    await prefs.setStringList(
      _countsPref,
      _counts.entries.map((e) => '${e.key.name}:${e.value}').toList(),
    );
  }

  static List<String> _names(Set<StrategyType> types) =>
      types.map((t) => t.name).toList();

  static StrategyType? _typeByName(String name) =>
      StrategyType.values.where((t) => t.name == name).firstOrNull;

  static Iterable<StrategyType> _typesFromNames(List<String>? names) =>
      (names ?? const <String>[]).map(_typeByName).whereType<StrategyType>();
}
